import{_ as t}from"./chunks/login.D00YWU-l.js";import{_ as o,o as a,c as r,a3 as n}from"./chunks/framework.Ki30n65y.js";const s="/depgate/screenshots/access-sso.png",i="/depgate/screenshots/sso-provider-new.png",d="/depgate/screenshots/sso-test.png",l="/depgate/screenshots/sso-provider-saml.png",w=JSON.parse('{"title":"Single sign-on","description":"","frontmatter":{},"headers":[],"relativePath":"admin/sso.md","filePath":"admin/sso.md"}'),h={name:"admin/sso.md"};function c(g,e,p,u,m,y){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="single-sign-on" tabindex="-1">Single sign-on <a class="header-anchor" href="#single-sign-on" aria-label="Permalink to &quot;Single sign-on&quot;">​</a></h1><p>People can sign in with your company identity provider instead of a DepGate password. DepGate speaks <strong>OpenID Connect (OIDC)</strong> and <strong>SAML 2.0</strong>, so it works with any provider that offers either: Okta, Microsoft Entra ID, Google, Auth0, Keycloak, Ping, OneLogin, ADFS and others. Prefer OIDC when your provider offers both; use SAML when it is the only option or your policy requires it (<a href="#saml-2-0">SAML</a>).</p><p><strong>The identity provider proves who someone is. DepGate decides what they can do.</strong> The role always comes from <strong>Access → Users</strong> (<a href="./users">Access</a>), never from the provider.</p><p><img src="'+s+'" alt="The Single sign-on tab"></p><table tabindex="0"><thead><tr><th>Person</th><th>Listed under Access → Users?</th><th>Result of single sign-on</th></tr></thead><tbody><tr><td><a href="mailto:ravi@yourcompany.com" target="_blank" rel="noreferrer">ravi@yourcompany.com</a></td><td>Yes, Security</td><td>Signed in as <strong>Security</strong></td></tr><tr><td><a href="mailto:dev@yourcompany.com" target="_blank" rel="noreferrer">dev@yourcompany.com</a></td><td>Yes, User</td><td>Signed in as <strong>User</strong></td></tr><tr><td><a href="mailto:new@yourcompany.com" target="_blank" rel="noreferrer">new@yourcompany.com</a></td><td>No</td><td>Added as <strong>User</strong> and signed in (can be turned off)</td></tr><tr><td><a href="mailto:someone@gmail.com" target="_blank" rel="noreferrer">someone@gmail.com</a></td><td>No</td><td><strong>Refused</strong>: the domain is not allowed</td></tr><tr><td>Anyone</td><td>Yes, but disabled</td><td><strong>Refused</strong></td></tr></tbody></table><p>Password sign-in keeps working next to single sign-on. Keep at least one Security user with a password: password sign-in never depends on the provider, so an outage cannot lock you out.</p><h2 id="_1-allow-your-email-domains" tabindex="-1">1. Allow your email domains <a class="header-anchor" href="#_1-allow-your-email-domains" aria-label="Permalink to &quot;1. Allow your email domains&quot;">​</a></h2><p>Under <strong>Access → Single sign-on → Who may sign in</strong>:</p><ol><li>Add each domain people sign in with to <strong>Allowed sign-in domains</strong>, for example <code>yourcompany.com</code>. Matching is exact: <code>yourcompany.com</code> does not allow <code>sub.yourcompany.com</code> or <code>evil-yourcompany.com</code>.</li><li>Choose whether to <strong>Add new people automatically</strong>. On: anyone in an allowed domain who is not under Users yet joins as User on their first sign-in. Off: only people you added can sign in.</li><li>Choose <strong>Save</strong>.</li></ol><p>A provider cannot be turned on while the list is empty. Without it, any account the provider vouches for could sign in, which with Google means any Gmail account.</p><h2 id="_2-register-depgate-at-the-provider" tabindex="-1">2. Register DepGate at the provider <a class="header-anchor" href="#_2-register-depgate-at-the-provider" aria-label="Permalink to &quot;2. Register DepGate at the provider&quot;">​</a></h2><p>Create an application at your identity provider:</p><ul><li>Type: <strong>web application</strong>, confidential client (it has a client secret).</li><li>Grant: <strong>authorization code</strong>. DepGate always uses PKCE (S256).</li><li>Scopes: <code>openid email profile</code>.</li><li><strong>Redirect URI</strong>: <code>https://&lt;your DepGate&gt;/api/auth/sso/&lt;id&gt;/callback</code>. Choose <strong>Add provider</strong> in step 3 to see the exact value: it is in the summary on the right of the page, with a copy button, before you fill anything in.</li></ul><p>Note the <strong>issuer URL</strong>, <strong>client ID</strong> and <strong>client secret</strong>. The setup guides below say where each provider shows them.</p><h2 id="_3-add-the-provider-in-depgate" tabindex="-1">3. Add the provider in DepGate <a class="header-anchor" href="#_3-add-the-provider-in-depgate" aria-label="Permalink to &quot;3. Add the provider in DepGate&quot;">​</a></h2><p>On the same tab, under <strong>Identity providers</strong>, choose <strong>Add provider</strong>:</p><table tabindex="0"><thead><tr><th>Field</th><th>What to enter</th></tr></thead><tbody><tr><td>Name</td><td>Shown to admins and in the Audit Log, e.g. <code>Corporate SSO</code>.</td></tr><tr><td>Button label</td><td>Shown on the login page, e.g. <code>Sign in with Corporate SSO</code>.</td></tr><tr><td>Issuer URL</td><td>As the provider publishes it. The link under the field opens its discovery document (<code>&lt;issuer&gt;/.well-known/openid-configuration</code>); <strong>Discover</strong> checks it. A missing or extra trailing <code>/</code> is corrected to the provider&#39;s spelling (Auth0 issuers end with <code>/</code>).</td></tr><tr><td>Client ID, Client secret</td><td>From the application you registered. The secret is stored encrypted and never shown again; leave it blank on edit to keep it.</td></tr><tr><td>Scopes</td><td>Default <code>openid email profile</code>.</td></tr><tr><td>Email claim</td><td>The claim holding the email address. Default <code>email</code>.</td></tr><tr><td>Require email_verified</td><td>Default on. Turn off only for providers that never send it (Entra ID).</td></tr><tr><td>Required claims</td><td>Optional <code>claim = value</code> rows every sign-in must carry, e.g. <code>hd = yourcompany.com</code> for Google Workspace or <code>tid = &lt;tenant id&gt;</code> for Entra ID.</td></tr></tbody></table><p><strong>Advanced</strong>: enter the endpoints by hand for providers without a discovery document, switch client authentication between <code>client_secret_basic</code> and <code>client_secret_post</code>, set the allowed clock skew, or add authorization parameters such as <code>prompt = login</code>.</p><p><img src="'+i+'" alt="Adding an OpenID Connect provider"></p><p>Adding and editing a provider is a page of its own. The <strong>Summary</strong> on the right shows what will be saved, the <strong>Redirect URI</strong> to register at the provider (<strong>Show all URLs</strong> adds the <strong>Initiate login URI</strong>, for a provider dashboard tile, and the <strong>Post-logout URI</strong>), a short checklist, and what Save still needs. Choose <strong>Create provider</strong>; the page then becomes the provider&#39;s edit page, where <strong>Test sign-in</strong> is available. Turn on <strong>Show on the login page</strong> in the summary, or use the switch in the list. Leaving with unsaved changes asks first. Choose a provider&#39;s name, or the eye icon, to see its details without editing.</p><p>If DepGate cannot reach the provider, or the domain list is empty, the provider is saved <strong>turned off</strong> and the reason is shown.</p><h2 id="_4-test-it" tabindex="-1">4. Test it <a class="header-anchor" href="#_4-test-it" aria-label="Permalink to &quot;4. Test it&quot;">​</a></h2><p>Open the provider (its name, or the eye icon) or <strong>Edit</strong> it, and choose <strong>Test sign-in</strong>. A window opens at the provider; sign in as the person you want to check. DepGate shows the claims it received, each check (email, verified email, required claims, allowed domain) and what a real sign-in would do, for example <em>Would sign in as <a href="mailto:ravi@yourcompany.com" target="_blank" rel="noreferrer">ravi@yourcompany.com</a> with role Security</em>. A test signs nobody in and creates nothing, and works while the provider is still turned off.</p><p><img src="'+d+'" alt="The result of a test sign-in"></p><h2 id="what-people-see" tabindex="-1">What people see <a class="header-anchor" href="#what-people-see" aria-label="Permalink to &quot;What people see&quot;">​</a></h2><p>The login page shows one button per provider that is turned on, under the email and password form. After signing in at the provider they return to the page they were opening.</p><p><img src="'+t+'" alt="The sign-in page with a single sign-on button"></p><p>If DepGate refuses a sign-in, the login page says why in plain words, for example <em>Your account&#39;s domain is not allowed to sign in</em>. The details go to the Audit Log.</p><h2 id="audit" tabindex="-1">Audit <a class="header-anchor" href="#audit" aria-label="Permalink to &quot;Audit&quot;">​</a></h2><p>Every sign-in, by password or single sign-on, is recorded in the <a href="./audit-log">Audit Log</a> under the <strong>Sign in</strong> feature:</p><table tabindex="0"><thead><tr><th>Entry</th><th>When</th></tr></thead><tbody><tr><td>Sign-in succeeded</td><td>With the method (password, OIDC, SAML), the provider and the role.</td></tr><tr><td>Sign-in failed</td><td>With the reason: wrong password, unknown account, disabled, domain not allowed, unverified email, required claim missing, not invited, another provider account already linked, response failed validation, expired request, provider error or unreachable, too many attempts.</td></tr><tr><td>Identity linked</td><td>A listed person signed in with a provider for the first time.</td></tr><tr><td>User provisioned</td><td>An unlisted person signed in for the first time and was added as User (under <strong>Access</strong>).</td></tr><tr><td>Provider created / updated / deleted, Sign-in settings changed</td><td>Changes to this setup (under <strong>Access</strong>).</td></tr></tbody></table><p>Filter by <strong>Feature</strong> and <strong>Action</strong>. Changes an admin makes while signed in with single sign-on record that method too. <code>depgate_logins_total</code> counts every attempt by method and result.</p><h2 id="when-someone-leaves" tabindex="-1">When someone leaves <a class="header-anchor" href="#when-someone-leaves" aria-label="Permalink to &quot;When someone leaves&quot;">​</a></h2><p>Removing a person at the identity provider stops new sign-ins, but sessions already open keep working until they expire, and a <strong>registry token lasts 30 days</strong> by default. When someone leaves:</p><ol><li>Remove them at the identity provider.</li><li>In DepGate, choose <strong>⋮ → Disable</strong> on their row. Their browser sessions and registry tokens stop working at once.</li></ol><p>Consider a shorter registry token lifetime under <strong>Settings → Repositories → Gateway security</strong>.</p><h2 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h2><ul><li>An account is tied to the provider account it first signed in with. If another account at that provider later carries the same email, DepGate refuses it.</li><li>The ID token&#39;s signature is always checked against the provider&#39;s published keys, as are its issuer, audience, expiry and nonce. Unsigned and HMAC-signed tokens are refused.</li><li>Use your organization&#39;s own issuer, not a shared multi-tenant one (Entra <code>/common</code>), or pin the organization with a required claim.</li><li>Plain <code>http://</code> issuers are refused except on <code>localhost</code>.</li><li>SAML responses are checked as described in <a href="#what-depgate-checks-on-every-saml-response">What DepGate checks on every SAML response</a>.</li></ul><h2 id="provider-setup-guides" tabindex="-1">Provider setup guides <a class="header-anchor" href="#provider-setup-guides" aria-label="Permalink to &quot;Provider setup guides&quot;">​</a></h2><p>These are the places each provider shows the values above. Register the redirect URI DepGate shows after the first save.</p><h3 id="okta" tabindex="-1">Okta <a class="header-anchor" href="#okta" aria-label="Permalink to &quot;Okta&quot;">​</a></h3><ol><li><strong>Applications → Create App Integration → OIDC - OpenID Connect → Web Application</strong>.</li><li><strong>Sign-in redirect URIs</strong>: DepGate&#39;s Redirect URI. <strong>Sign-out redirect URIs</strong>: the Post-logout redirect URI. To show DepGate on the Okta dashboard, set <strong>Initiate login URI</strong> to DepGate&#39;s Initiate login URI and <strong>Login initiated by</strong> to <em>Either Okta or App</em>.</li><li><strong>Assignments</strong>: assign the people or groups who may use DepGate.</li><li>Issuer: <code>https://&lt;your-org&gt;.okta.com</code> (org authorization server) or <code>https://&lt;your-org&gt;.okta.com/oauth2/default</code> (custom). Client ID and secret are on the application&#39;s <strong>General</strong> tab.</li></ol><h3 id="microsoft-entra-id" tabindex="-1">Microsoft Entra ID <a class="header-anchor" href="#microsoft-entra-id" aria-label="Permalink to &quot;Microsoft Entra ID&quot;">​</a></h3><ol><li><strong>App registrations → New registration</strong>, single tenant. Redirect URI: <strong>Web</strong>, DepGate&#39;s Redirect URI.</li><li><strong>Certificates &amp; secrets → New client secret</strong>.</li><li>Issuer: <code>https://login.microsoftonline.com/&lt;tenant-id&gt;/v2.0</code> (never <code>/common</code>). Client ID is the <em>Application (client) ID</em>.</li><li>Entra does not send <code>email_verified</code>: turn <strong>Require email_verified</strong> off, and add the required claim <code>tid = &lt;tenant-id&gt;</code>. If <code>email</code> is empty for your accounts, set <strong>Email claim</strong> to <code>preferred_username</code>.</li></ol><h3 id="google" tabindex="-1">Google <a class="header-anchor" href="#google" aria-label="Permalink to &quot;Google&quot;">​</a></h3><ol><li>Google Cloud console → <strong>APIs &amp; Services → Credentials → Create credentials → OAuth client ID → Web application</strong>.</li><li><strong>Authorized redirect URIs</strong>: DepGate&#39;s Redirect URI.</li><li>Issuer: <code>https://accounts.google.com</code>.</li><li>Any Gmail account can sign in to Google, so keep your company domain in the allowed list and add the required claim <code>hd = yourcompany.com</code> (Google Workspace accounts carry it, personal accounts do not).</li></ol><h3 id="auth0" tabindex="-1">Auth0 <a class="header-anchor" href="#auth0" aria-label="Permalink to &quot;Auth0&quot;">​</a></h3><ol><li><strong>Applications → Create Application → Regular Web Applications</strong>.</li><li><strong>Allowed Callback URLs</strong>: DepGate&#39;s Redirect URI.</li><li>Issuer: <code>https://&lt;tenant&gt;.&lt;region&gt;.auth0.com/</code> (with the trailing slash, as Auth0 publishes it). Client ID and secret are on the <strong>Settings</strong> tab.</li></ol><h3 id="keycloak" tabindex="-1">Keycloak <a class="header-anchor" href="#keycloak" aria-label="Permalink to &quot;Keycloak&quot;">​</a></h3><ol><li>In the realm, <strong>Clients → Create client</strong>, OpenID Connect, <strong>Client authentication</strong> on, <strong>Standard flow</strong> on.</li><li><strong>Valid redirect URIs</strong>: DepGate&#39;s Redirect URI.</li><li>Issuer: <code>https://&lt;keycloak&gt;/realms/&lt;realm&gt;</code>. The secret is on the client&#39;s <strong>Credentials</strong> tab.</li></ol><h3 id="github" tabindex="-1">GitHub <a class="header-anchor" href="#github" aria-label="Permalink to &quot;GitHub&quot;">​</a></h3><p>GitHub sign-in is OAuth 2.0, not OpenID Connect: it issues no ID token. It does not work as an OIDC provider.</p><h2 id="saml-2-0" tabindex="-1">SAML 2.0 <a class="header-anchor" href="#saml-2-0" aria-label="Permalink to &quot;SAML 2.0&quot;">​</a></h2><p>DepGate is a SAML service provider (SP). The sign-in always starts at DepGate (SP-initiated): DepGate sends an AuthnRequest with the HTTP-Redirect binding, and the IdP posts the response back to DepGate&#39;s ACS URL with the HTTP-POST binding. The allowed domains, adding new people, roles, audit and leaver guidance above apply exactly as for OIDC.</p><h3 id="_1-register-depgate-at-the-idp" tabindex="-1">1. Register DepGate at the IdP <a class="header-anchor" href="#_1-register-depgate-at-the-idp" aria-label="Permalink to &quot;1. Register DepGate at the IdP&quot;">​</a></h3><p>Choose <strong>Add provider</strong>, protocol <strong>SAML 2.0</strong>. The summary on the right shows, before you fill anything in:</p><table tabindex="0"><thead><tr><th>Value</th><th>What it is</th></tr></thead><tbody><tr><td><strong>SP entity ID</strong></td><td><code>https://&lt;your DepGate&gt;/api/auth/saml/&lt;id&gt;/metadata</code>. The IdP calls it <em>Entity ID</em>, <em>Audience URI</em> or <em>Identifier</em>.</td></tr><tr><td><strong>ACS URL</strong></td><td><code>https://&lt;your DepGate&gt;/api/auth/saml/&lt;id&gt;/acs</code>. The IdP calls it <em>Assertion Consumer Service URL</em>, <em>Single sign-on URL</em> or <em>Reply URL</em>. HTTP-POST binding.</td></tr><tr><td><strong>SP metadata</strong></td><td>After the first save, a download of DepGate&#39;s SP metadata, for IdPs that import it. It is also served at the SP entity ID.</td></tr></tbody></table><p>At the IdP, ask for:</p><ul><li><strong>Signed assertions</strong> (most IdPs call it <em>Sign assertion</em>); signing the response as well does no harm.</li><li><strong>NameID format</strong> <code>emailAddress</code>, with the user&#39;s email; or another stable format plus an email attribute.</li><li>No encryption, unless you turn on <strong>Accept encrypted assertions</strong> (below).</li></ul><h3 id="_2-add-the-idp-in-depgate" tabindex="-1">2. Add the IdP in DepGate <a class="header-anchor" href="#_2-add-the-idp-in-depgate" aria-label="Permalink to &quot;2. Add the IdP in DepGate&quot;">​</a></h3><p><img src="'+l+'" alt="Adding a SAML provider"></p><p><strong>Identity provider</strong></p><table tabindex="0"><thead><tr><th>Field</th><th>What to enter</th></tr></thead><tbody><tr><td>IdP metadata</td><td><strong>Metadata URL</strong> (DepGate reads it now, and again on every save, so a new IdP certificate is picked up), <strong>Paste XML</strong>, or <strong>Upload file</strong>. <strong>Read metadata</strong> fills the three fields below.</td></tr><tr><td>IdP entity ID</td><td>Assertions must be issued by exactly this.</td></tr><tr><td>IdP SSO URL</td><td>The IdP&#39;s HTTP-Redirect endpoint. <code>https://</code> (plain <code>http://</code> only on <code>localhost</code>).</td></tr><tr><td>IdP signing certificates</td><td>One, or two while the IdP rotates its key. Signatures are checked against these only, never against a certificate inside a response. Each shows its subject, issuer, SHA-256 fingerprint and expiry; DepGate warns 30 days before expiry, and a provider whose certificates have all expired cannot be turned on.</td></tr></tbody></table><p><strong>Attributes</strong></p><table tabindex="0"><thead><tr><th>Field</th><th>What to enter</th></tr></thead><tbody><tr><td>NameID format</td><td>What DepGate asks for. Default <em>Email address</em>.</td></tr><tr><td>Email attribute</td><td>Empty: the NameID when it is an email address, otherwise an attribute named <code>email</code>. Otherwise the attribute&#39;s name, e.g. <code>http://schemas.xmlsoap.org/ws/2005/05/identity/claims/emailaddress</code>.</td></tr><tr><td>Subject attribute</td><td>What ties the DepGate account to the IdP account. Empty: the NameID. A stable employee or object ID is better when the IdP has one: emails can change. A <em>transient</em> NameID changes at every sign-in, so it needs a subject attribute.</td></tr><tr><td>Required attributes</td><td>Optional <code>attribute = value</code> rows every sign-in must carry, e.g. <code>department = Engineering</code>. A multi-valued attribute matches when it holds the value.</td></tr></tbody></table><p><strong>Security</strong></p><table tabindex="0"><thead><tr><th>Field</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td>Require signed assertion</td><td>On</td><td>The assertion itself must be signed. A signed response around an unsigned assertion is refused. Off: the whole response must be signed instead; an unsigned response is always refused.</td></tr><tr><td>Sign authentication requests</td><td>Off</td><td>For IdPs that require signed AuthnRequests (RSA-SHA256). Needs an SP certificate. Turned on automatically when the IdP metadata says <code>WantAuthnRequestsSigned</code>.</td></tr><tr><td>Accept encrypted assertions</td><td>Off</td><td>For IdPs that encrypt assertions. Needs an SP certificate. An encrypted assertion still has to be signed.</td></tr><tr><td>SP certificate and private key</td><td>None</td><td><strong>Generate</strong> creates a self-signed RSA 2048 / SHA-256 certificate valid 5 years, or <strong>Upload</strong> your own certificate and unencrypted PEM private key. The key is stored encrypted and never shown again. Give the IdP the certificate (or the SP metadata, which includes it).</td></tr><tr><td>Allowed clock skew</td><td>60 s</td><td>Up to 300 s.</td></tr></tbody></table><p>A SAML provider saved with an unreadable metadata URL or an expired certificate is kept <strong>turned off</strong> with the reason, like an unreachable OIDC provider.</p><h3 id="_3-test-it" tabindex="-1">3. Test it <a class="header-anchor" href="#_3-test-it" aria-label="Permalink to &quot;3. Test it&quot;">​</a></h3><p><strong>Test sign-in</strong> works as for OIDC. For SAML it shows the <strong>NameID</strong>, its format and every attribute the IdP sent, and the same checks.</p><h3 id="what-depgate-checks-on-every-saml-response" tabindex="-1">What DepGate checks on every SAML response <a class="header-anchor" href="#what-depgate-checks-on-every-saml-response" aria-label="Permalink to &quot;What DepGate checks on every SAML response&quot;">​</a></h3><p>The XML signature against the configured certificates (and nothing else); the assertion&#39;s <strong>Issuer</strong> equals the IdP entity ID; <strong>Audience</strong> equals the SP entity ID; the response <strong>Destination</strong> (when present) and the <strong>Recipient</strong> equal the ACS URL; <strong>InResponseTo</strong> names the request this browser&#39;s sign-in sent, which is used once; <strong>NotBefore / NotOnOrAfter</strong> with the clock skew; and each assertion ID is remembered until it expires, so a replayed assertion is refused. Responses with a DOCTYPE are refused, as are responses DepGate did not ask for (IdP-initiated sign-in, e.g. a dashboard tile that posts straight to the ACS). For a dashboard tile, point it at the <strong>Initiate login URI</strong> <code>https://&lt;your DepGate&gt;/api/auth/sso/&lt;id&gt;/start</code> where the IdP allows a plain link.</p><h3 id="saml-setup-guides" tabindex="-1">SAML setup guides <a class="header-anchor" href="#saml-setup-guides" aria-label="Permalink to &quot;SAML setup guides&quot;">​</a></h3><h4 id="okta-1" tabindex="-1">Okta <a class="header-anchor" href="#okta-1" aria-label="Permalink to &quot;Okta&quot;">​</a></h4><ol><li><strong>Applications → Create App Integration → SAML 2.0</strong>.</li><li><strong>Single sign-on URL</strong>: DepGate&#39;s ACS URL (<em>Use this for Recipient URL and Destination URL</em> ticked). <strong>Audience URI (SP Entity ID)</strong>: DepGate&#39;s SP entity ID. <strong>Name ID format</strong>: EmailAddress, <strong>Application username</strong>: Email.</li><li><strong>Assignments</strong>: assign the people or groups who may use DepGate.</li><li>Metadata URL: the app&#39;s <strong>Sign On</strong> tab → <em>Metadata URL</em>.</li></ol><h4 id="microsoft-entra-id-1" tabindex="-1">Microsoft Entra ID <a class="header-anchor" href="#microsoft-entra-id-1" aria-label="Permalink to &quot;Microsoft Entra ID&quot;">​</a></h4><ol><li><strong>Enterprise applications → New application → Create your own application</strong> (non-gallery) → <strong>Single sign-on → SAML</strong>.</li><li><strong>Identifier (Entity ID)</strong>: DepGate&#39;s SP entity ID. <strong>Reply URL</strong>: DepGate&#39;s ACS URL.</li><li>Metadata URL: <strong>App Federation Metadata Url</strong> in section 3.</li><li>Entra&#39;s NameID is the user principal name by default. If that is not the email, set <strong>Email attribute</strong> to <code>http://schemas.xmlsoap.org/ws/2005/05/identity/claims/emailaddress</code>, and consider <strong>Subject attribute</strong> <code>http://schemas.microsoft.com/identity/claims/objectidentifier</code>.</li></ol><h4 id="google-workspace" tabindex="-1">Google Workspace <a class="header-anchor" href="#google-workspace" aria-label="Permalink to &quot;Google Workspace&quot;">​</a></h4><ol><li>Admin console → <strong>Apps → Web and mobile apps → Add app → Add custom SAML app</strong>.</li><li>Download the IdP metadata in step 2 and use <strong>Upload file</strong> in DepGate.</li><li><strong>ACS URL</strong>: DepGate&#39;s ACS URL. <strong>Entity ID</strong>: DepGate&#39;s SP entity ID. <strong>Name ID format</strong> EMAIL, <strong>Name ID</strong> Basic Information → Primary email.</li><li>Turn the app on for the organizational units that may use DepGate. Only Workspace accounts can use it; personal Gmail accounts cannot.</li></ol><h4 id="auth0-1" tabindex="-1">Auth0 <a class="header-anchor" href="#auth0-1" aria-label="Permalink to &quot;Auth0&quot;">​</a></h4><ol><li><strong>Applications → Create Application → Regular Web Applications → Addons → SAML2 Web App</strong>.</li><li><strong>Application Callback URL</strong>: DepGate&#39;s ACS URL. In Settings, set <code>&quot;audience&quot;</code> to DepGate&#39;s SP entity ID.</li><li>Metadata URL: <code>https://&lt;tenant&gt;.&lt;region&gt;.auth0.com/samlp/metadata/&lt;client id&gt;</code>.</li></ol><h4 id="keycloak-1" tabindex="-1">Keycloak <a class="header-anchor" href="#keycloak-1" aria-label="Permalink to &quot;Keycloak&quot;">​</a></h4><ol><li>In the realm, <strong>Clients → Create client</strong>, type <strong>SAML</strong>. Client ID: DepGate&#39;s SP entity ID.</li><li><strong>Valid redirect URIs</strong> and <strong>Assertion Consumer Service POST Binding URL</strong>: DepGate&#39;s ACS URL.</li><li><strong>Signature and Encryption</strong>: Sign documents and Sign assertions on. <strong>SAML capabilities</strong>: Name ID format <em>email</em>, Force name ID format on.</li><li><strong>Keys</strong>: Keycloak requires signed requests by default (<em>Client signature required</em>). Either turn that off, or turn on <strong>Sign authentication requests</strong> in DepGate, <strong>Generate</strong> the SP certificate and import DepGate&#39;s SP metadata here.</li><li>Metadata URL: <code>https://&lt;keycloak&gt;/realms/&lt;realm&gt;/protocol/saml/descriptor</code>.</li></ol>',83)])])}const v=o(h,[["render",c]]);export{w as __pageData,v as default};
